            for c in range(lo+1,hi):
                if out[r1][c]==0:out[r1][c]=5
        elif c1==c2:
            lo,hi=sorted((r1,r2))
            for r in range(lo+1,hi):
                if out[r][c1]==0:out[r][c1]=5
