            if 0 <= rr < h and 0 <= cc < w: out[rr][cc] = 5
        rr, cc = cells[2]
        if 0 <= rr < h and 0 <= cc < w: out[rr][cc] = 1

    if 2 in starts:
        r, c = starts[2]
        cells = [(r, c - k) for k in range(1, 5)]
        paths[2] = [(r, c)] + cells
        for rr, cc in cells[:-1]:
            if 0 <= rr < h and 0 <= cc < w: out[rr][cc] = 5
        rr, cc = cells[-1]
        if 0 <= rr < h and 0 <= cc < w: out[rr][cc] = 2

    if 3 in starts:
        r, c = starts[3]
        cells = [(r + k, c) for k in range(1, 4)]
        paths[3] = [(r, c)] + cells
        for rr, cc in cells[:-1]:
            if 0 <= rr < h and 0 <= cc < w: out[rr][cc] = 5
        rr, cc = cells[-1]
        if 0 <= rr < h and 0 <= cc < w: out[rr][cc] = 3

    if 6 in starts:
        r, c = starts[6]
        cells = [(r - k, c) for k in range(1, 7)]
        paths[6] = [(r, c)] + cells
        for rr, cc in cells[:-1]:
            if 0 <= rr < h and 0 <= cc < w: out[rr][cc] = 5
        rr, cc = cells[-1]
        if 0 <= rr < h and 0 <= cc < w: out[rr][cc] = 6

    # Crossings between generated rays become 4, followed by a diagonal 4 ray down-left.
    all_paths = [set(cells) for cells in paths.values()]
    crossings = set()
    for i in range(len(all_paths)):
